-- Platform database baseline (two-database split). Generated from the single-database schema as of V131,
-- minus every foreign key that crosses the platform/school boundary (integrity across the two
-- databases is enforced in the application, not by the database).

CREATE TABLE `crm_activities` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `lead_id` bigint DEFAULT NULL,
  `organisation_id` bigint DEFAULT NULL,
  `type` varchar(20) NOT NULL,
  `body` text NOT NULL,
  `occurred_at` datetime(6) NOT NULL,
  `author_id` bigint DEFAULT NULL,
  `created_at` datetime(6) NOT NULL,
  `updated_at` datetime(6) NOT NULL,
  `created_by` bigint DEFAULT NULL,
  `updated_by` bigint DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `fk_crm_activities_author` (`author_id`),
  KEY `idx_crm_activities_lead` (`lead_id`),
  KEY `idx_crm_activities_organisation` (`organisation_id`),
  CONSTRAINT `chk_crm_activities_one_owner` CHECK ((((`lead_id` is not null) and (`organisation_id` is null)) or ((`lead_id` is null) and (`organisation_id` is not null))))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE `crm_contacts` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `lead_id` bigint DEFAULT NULL,
  `organisation_id` bigint DEFAULT NULL,
  `name` varchar(255) NOT NULL,
  `role_title` varchar(255) DEFAULT NULL,
  `email` varchar(255) DEFAULT NULL,
  `phone` varchar(50) DEFAULT NULL,
  `created_at` datetime(6) NOT NULL,
  `updated_at` datetime(6) NOT NULL,
  `created_by` bigint DEFAULT NULL,
  `updated_by` bigint DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_crm_contacts_lead` (`lead_id`),
  KEY `idx_crm_contacts_organisation` (`organisation_id`),
  CONSTRAINT `chk_crm_contacts_one_owner` CHECK ((((`lead_id` is not null) and (`organisation_id` is null)) or ((`lead_id` is null) and (`organisation_id` is not null))))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE `crm_leads` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `school_name` varchar(255) NOT NULL,
  `source` varchar(20) NOT NULL,
  `stage` varchar(20) NOT NULL,
  `estimated_student_count` int DEFAULT NULL,
  `owner_id` bigint DEFAULT NULL,
  `notes` text,
  `converted_organisation_id` bigint DEFAULT NULL,
  `created_at` datetime(6) NOT NULL,
  `updated_at` datetime(6) NOT NULL,
  `created_by` bigint DEFAULT NULL,
  `updated_by` bigint DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `fk_crm_leads_owner` (`owner_id`),
  KEY `fk_crm_leads_converted_org` (`converted_organisation_id`),
  KEY `idx_crm_leads_stage` (`stage`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE `crm_tasks` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `lead_id` bigint DEFAULT NULL,
  `organisation_id` bigint DEFAULT NULL,
  `title` varchar(255) NOT NULL,
  `due_at` datetime(6) NOT NULL,
  `assignee_id` bigint DEFAULT NULL,
  `completed_at` datetime(6) DEFAULT NULL,
  `created_at` datetime(6) NOT NULL,
  `updated_at` datetime(6) NOT NULL,
  `created_by` bigint DEFAULT NULL,
  `updated_by` bigint DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `fk_crm_tasks_assignee` (`assignee_id`),
  KEY `idx_crm_tasks_lead` (`lead_id`),
  KEY `idx_crm_tasks_organisation` (`organisation_id`),
  KEY `idx_crm_tasks_due` (`completed_at`,`due_at`),
  CONSTRAINT `chk_crm_tasks_one_owner` CHECK ((((`lead_id` is not null) and (`organisation_id` is null)) or ((`lead_id` is null) and (`organisation_id` is not null))))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE `external_services` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `service_key` varchar(50) NOT NULL,
  `display_name` varchar(100) NOT NULL,
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `created_by` bigint DEFAULT NULL,
  `updated_by` bigint DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `service_key` (`service_key`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE `organisation_external_services` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `organisation_id` bigint NOT NULL,
  `external_service_id` bigint NOT NULL,
  `enabled` tinyint(1) NOT NULL DEFAULT '0',
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `created_by` bigint DEFAULT NULL,
  `updated_by` bigint DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_org_ext_services` (`organisation_id`,`external_service_id`),
  KEY `fk_org_ext_services_service` (`external_service_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE `organisation_module_settings` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `organisation_id` bigint NOT NULL,
  `module_code` varchar(40) NOT NULL,
  `enabled` tinyint(1) NOT NULL,
  `note` varchar(255) DEFAULT NULL,
  `created_at` datetime(6) NOT NULL,
  `updated_at` datetime(6) NOT NULL,
  `created_by` bigint DEFAULT NULL,
  `updated_by` bigint DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_org_module_settings_org` (`organisation_id`,`module_code`,`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE `organisations` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `name` varchar(255) NOT NULL,
  `legal_name` varchar(255) DEFAULT NULL,
  `slug` varchar(100) NOT NULL,
  `status` varchar(20) NOT NULL,
  `created_at` datetime(6) NOT NULL,
  `updated_at` datetime(6) NOT NULL,
  `created_by` bigint DEFAULT NULL,
  `updated_by` bigint DEFAULT NULL,
  `organisation_type` varchar(20) NOT NULL DEFAULT 'SCHOOL',
  `board` varchar(20) DEFAULT NULL,
  `school_code` varchar(50) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_organisations_slug` (`slug`),
  UNIQUE KEY `uq_organisations_school_code` (`school_code`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE `plans` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `code` varchar(30) NOT NULL,
  `name` varchar(100) NOT NULL,
  `price_per_student_per_year` decimal(10,2) NOT NULL,
  `status` varchar(20) NOT NULL,
  `created_at` datetime(6) NOT NULL,
  `updated_at` datetime(6) NOT NULL,
  `created_by` bigint DEFAULT NULL,
  `updated_by` bigint DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_plans_code` (`code`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE `platform_admins` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `name` varchar(150) NOT NULL,
  `email` varchar(255) NOT NULL,
  `password_hash` varchar(255) NOT NULL,
  `status` varchar(20) NOT NULL,
  `created_at` datetime(6) NOT NULL,
  `updated_at` datetime(6) NOT NULL,
  `created_by` bigint DEFAULT NULL,
  `updated_by` bigint DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_platform_admins_email` (`email`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE `platform_invoices` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `organisation_id` bigint NOT NULL,
  `subscription_id` bigint NOT NULL,
  `period_start` date NOT NULL,
  `period_end` date NOT NULL,
  `student_count_at_billing` int NOT NULL,
  `amount` decimal(12,2) NOT NULL,
  `status` varchar(20) NOT NULL,
  `issued_at` datetime(6) NOT NULL,
  `due_date` date NOT NULL,
  `paid_at` datetime(6) DEFAULT NULL,
  `created_at` datetime(6) NOT NULL,
  `updated_at` datetime(6) NOT NULL,
  `created_by` bigint DEFAULT NULL,
  `updated_by` bigint DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `fk_platform_invoices_subscription` (`subscription_id`),
  KEY `idx_platform_invoices_org_status` (`organisation_id`,`status`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE `platform_settings` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `trial_days` int NOT NULL,
  `created_at` datetime(6) NOT NULL,
  `updated_at` datetime(6) NOT NULL,
  `created_by` bigint DEFAULT NULL,
  `updated_by` bigint DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE `subscriptions` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `organisation_id` bigint NOT NULL,
  `plan_id` bigint NOT NULL,
  `price_per_student_per_year` decimal(10,2) NOT NULL,
  `start_date` date NOT NULL,
  `end_date` date DEFAULT NULL,
  `status` varchar(20) NOT NULL,
  `created_at` datetime(6) NOT NULL,
  `updated_at` datetime(6) NOT NULL,
  `created_by` bigint DEFAULT NULL,
  `updated_by` bigint DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `fk_subscriptions_plan` (`plan_id`),
  KEY `idx_subscriptions_org_status` (`organisation_id`,`status`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE `support_tickets` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `organisation_id` bigint NOT NULL,
  `subject` varchar(255) NOT NULL,
  `description` text,
  `status` varchar(20) NOT NULL,
  `priority` varchar(20) NOT NULL,
  `requester_email` varchar(255) NOT NULL,
  `assignee_email` varchar(255) DEFAULT NULL,
  `created_at` datetime(6) NOT NULL,
  `updated_at` datetime(6) NOT NULL,
  `created_by` bigint DEFAULT NULL,
  `updated_by` bigint DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `fk_support_tickets_organisation` (`organisation_id`),
  KEY `idx_support_tickets_status` (`status`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE `timezones` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `name` varchar(64) NOT NULL,
  `region` varchar(32) NOT NULL,
  `created_at` datetime(6) NOT NULL,
  `updated_at` datetime(6) NOT NULL,
  `created_by` bigint DEFAULT NULL,
  `updated_by` bigint DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_timezones_name` (`name`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

ALTER TABLE `crm_activities` ADD CONSTRAINT `fk_crm_activities_author` FOREIGN KEY (`author_id`) REFERENCES `platform_admins` (`id`) ;
ALTER TABLE `crm_activities` ADD CONSTRAINT `fk_crm_activities_lead` FOREIGN KEY (`lead_id`) REFERENCES `crm_leads` (`id`) ;
ALTER TABLE `crm_activities` ADD CONSTRAINT `fk_crm_activities_organisation` FOREIGN KEY (`organisation_id`) REFERENCES `organisations` (`id`) ;
ALTER TABLE `crm_contacts` ADD CONSTRAINT `fk_crm_contacts_lead` FOREIGN KEY (`lead_id`) REFERENCES `crm_leads` (`id`) ;
ALTER TABLE `crm_contacts` ADD CONSTRAINT `fk_crm_contacts_organisation` FOREIGN KEY (`organisation_id`) REFERENCES `organisations` (`id`) ;
ALTER TABLE `crm_leads` ADD CONSTRAINT `fk_crm_leads_converted_org` FOREIGN KEY (`converted_organisation_id`) REFERENCES `organisations` (`id`) ;
ALTER TABLE `crm_leads` ADD CONSTRAINT `fk_crm_leads_owner` FOREIGN KEY (`owner_id`) REFERENCES `platform_admins` (`id`) ;
ALTER TABLE `crm_tasks` ADD CONSTRAINT `fk_crm_tasks_assignee` FOREIGN KEY (`assignee_id`) REFERENCES `platform_admins` (`id`) ;
ALTER TABLE `crm_tasks` ADD CONSTRAINT `fk_crm_tasks_lead` FOREIGN KEY (`lead_id`) REFERENCES `crm_leads` (`id`) ;
ALTER TABLE `crm_tasks` ADD CONSTRAINT `fk_crm_tasks_organisation` FOREIGN KEY (`organisation_id`) REFERENCES `organisations` (`id`) ;
ALTER TABLE `organisation_external_services` ADD CONSTRAINT `fk_org_ext_services_org` FOREIGN KEY (`organisation_id`) REFERENCES `organisations` (`id`) ;
ALTER TABLE `organisation_external_services` ADD CONSTRAINT `fk_org_ext_services_service` FOREIGN KEY (`external_service_id`) REFERENCES `external_services` (`id`) ;
ALTER TABLE `organisation_module_settings` ADD CONSTRAINT `fk_org_module_settings_org` FOREIGN KEY (`organisation_id`) REFERENCES `organisations` (`id`) ;
ALTER TABLE `platform_invoices` ADD CONSTRAINT `fk_platform_invoices_organisation` FOREIGN KEY (`organisation_id`) REFERENCES `organisations` (`id`) ;
ALTER TABLE `platform_invoices` ADD CONSTRAINT `fk_platform_invoices_subscription` FOREIGN KEY (`subscription_id`) REFERENCES `subscriptions` (`id`) ;
ALTER TABLE `subscriptions` ADD CONSTRAINT `fk_subscriptions_organisation` FOREIGN KEY (`organisation_id`) REFERENCES `organisations` (`id`) ;
ALTER TABLE `subscriptions` ADD CONSTRAINT `fk_subscriptions_plan` FOREIGN KEY (`plan_id`) REFERENCES `plans` (`id`) ;
ALTER TABLE `support_tickets` ADD CONSTRAINT `fk_support_tickets_organisation` FOREIGN KEY (`organisation_id`) REFERENCES `organisations` (`id`) ;

